def P(s,style='BodyX'):
 return Paragraph(s,styles[style])
def bullet(items):
 return ListFlowable([ListItem(P(x),leftIndent=0) for x in items],bulletType='bullet',leftIndent=14,bulletFontName='Helvetica',bulletFontSize=6,bulletColor=TEAL,spaceAfter=5)
def table(rows,widths=None):
 data=[]
 for r_i,row in enumerate(rows): data.append([Paragraph(str(c),ParagraphStyle(name=f'c{r_i}_{i}_{id(row)}',parent=styles['CellX'],fontName='Helvetica-Bold' if r_i==0 else 'Helvetica',textColor=colors.white if r_i==0 else colors.HexColor('#203243'))) for i,c in enumerate(row)])
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('GRID',(0,0),(-1,-1),0.35,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F5F7F6')])]))
 return t

def page(canvas,doc):
 canvas.saveState(); w,h=A4
 if doc.page>1:
  canvas.setFillColor(NAVY); canvas.rect(0,h-12*mm,w,12*mm,fill=1,stroke=0)
  canvas.setFillColor(colors.white); canvas.setFont('Helvetica-Bold',8); canvas.drawString(18*mm,h-8*mm,'NUMBER PLATE RECOGNITION | PROJECT GUIDE')
 canvas.setStrokeColor(LINE); canvas.line(18*mm,14*mm,w-18*mm,14*mm)
 canvas.setFillColor(MUTED); canvas.setFont('Helvetica',8); canvas.drawString(18*mm,9*mm,'Coastal Star, Nettoor | Presentation: 23 November 2026')
 canvas.drawRightString(w-18*mm,9*mm,str(doc.page)); canvas.restoreState()

story=[]
story += [Spacer(1,22*mm),P('NUMBER PLATE<br/>RECOGNITION','CoverTitleX'),P('Complete project technology, code logic, demonstration and troubleshooting guide','SubX'),Spacer(1,8*mm)]
story += [P('<b>Project:</b> Number Plate Recognition at Service Gate','BodyX'),P('<b>Presentation:</b> Coastal Star, Nettoor | 23 November 2026 | 3:30 PM','BodyX'),Spacer(1,6*mm),P('This guide explains how the current application works, what each project file does, how to prepare the booking CSV, and how to fix common problems. It is written for a student presentation and demo.','BodyX'),P('Accuracy and speed statement: the project has a 32.6 FPS warm benchmark for the detector on a still image. The current video path samples about 6 frames per second. The full application has not been verified at 24 FPS, and an 8 out of 10 unseen plate result has not yet been measured.','CalloutX'),Spacer(1,10*mm),P('Contents','H1x')]
contents=['1. Project summary and expected result','2. Technology and why it is used','3. System flow and recognition logic','4. Booking data: CSV import and manual entry','5. Source files and functions','6. Common errors and fixes','7. Demo and test plan','8. Current limits and next steps']
story += [bullet(contents),PageBreak()]
story += [P('1. Project summary and expected result','H1x'),P('The application reads a vehicle registration from a camera frame or an uploaded video. It detects the plate area, uses OCR to read the characters, cleans common reading mistakes, and searches today\'s service bookings. When a match exists, the screen can show the clearest recognized frame, the formatted plate, the customer, the appointment time, and the assigned advisor.','BodyX'),P('Example prepared for the presentation','H2x'),table([['Item','Expected demo value'],['Plate','KL 02 HB 1234'],['Customer','Gate Demo Presentation'],['Appointment','23 November 2026 at 3:30 PM'],['Advisor','Service Advisor 1']],[38*mm,135*mm]),Spacer(1,5),P('This value depends on the matching sample booking being present for the presentation date. If the data is changed, the screen should show the result from the current database or CSV. A plate with no booking should display as not matched. Frames where the application detects no valid plate should not create a result card.','BodyX'),P('Project parts','H2x'),bullet(['Camera or video input.','YOLO plate-area detector and Tesseract OCR.','Indian plate text cleanup and formatting.','Booking lookup in the database, with the sample CSV as a fallback.','Browser screen for bookings, recognition results and notification status.']),P('The application does not include WhatsApp messaging. The notification area is inside the application.','CalloutX'),PageBreak()]
story += [P('2. Technology and why it is used','H1x'),table([['Technology','Purpose in this project'],['Python','Main programming language for the API and image pipeline.'],['FastAPI + Uvicorn','Provides web pages and API endpoints; Uvicorn runs the web server.'],['OpenCV','Reads camera/video frames, crops image areas, rotates/prepares images, and saves preview images.'],['Ultralytics YOLO + PyTorch','Loads the trained model and predicts the plate bounding boxes. PyTorch is the model runtime.'],['Tesseract + pytesseract','OCR engine reads letters and digits from the detected plate crop.'],['SQLAlchemy + PostgreSQL','Stores advisors, bookings, detections and notifications. SQLAlchemy maps Python objects to database rows.'],['CSV / Python csv module','Imports booking rows and can supply sample bookings during lookup.'],['Pydantic','Checks request fields such as date, time and advisor ID.'],['HTML + CSS + JavaScript','Creates the login and dashboard pages, sends requests to the API and updates the visible results.'],['python-dotenv','Loads settings from a local environment file. Keep credentials private.']],[41*mm,132*mm]),Spacer(1,5),P('Why use each image stage?','H2x'),P('The detector finds where to look. OCR reads the characters inside that region. Plate cleanup checks a known Indian registration pattern and fixes common OCR character confusions only in the expected letter or digit positions. The booking lookup then uses the normalized plate text. Keeping these tasks separate makes it easier to find whether a failure comes from detection, OCR or booking data.','BodyX'),P('Main data records','H2x'),table([['Record','What it stores'],['Advisor','Advisor name, login, contact fields and active status.'],['Booking','Customer, vehicle number, date/time, service type, status and assigned advisor.'],['Detection','OCR plate text, confidence, image path, match status and optional booking link.'],['Notification','Detection link, advisor link, message, status and read/unread state.']],[40*mm,133*mm]),PageBreak()]
story += [P('3. System flow and recognition logic','H1x'),table([['Step','What the code does'],['1. Capture','OpenCV reads one frame from the webcam or video file.'],['2. Find plate','The detector applies the configured region of interest and runs YOLO. It tries the original crop and rotated orientations.'],['3. Crop','The best plate box is mapped back to the original frame and cropped.'],['4. Prepare OCR','OCR enlarges the crop, converts it to gray, denoises it, improves contrast and creates thresholded versions.'],['5. Read text','Tesseract tests one or more page segmentation modes with letters and digits allowed.'],['6. Clean plate','The code removes separators, corrects common O/0, I/1 and similar confusions in the proper positions, and validates the Indian registration pattern.'],['7. Match booking','The system checks today\'s database bookings for an exact plate. It may accept a unique booking one character away. It checks the sample CSV if the database did not match.'],['8. Show result','The interface presents the clearest recognized frame for each plate in an uploaded video, plus the plate and booking match details.']],[30*mm,143*mm]),P('Important lookup rules','H2x'),bullet(['The booking date is compared to today in the Asia/Kolkata time zone.','Exact normalized registration is preferred. Spaces and hyphens do not affect comparison.','A one-character fuzzy match is accepted only when there is exactly one candidate. If multiple candidates are close, the system does not guess.','CSV fallback rows currently need ISO booking dates (YYYY-MM-DD). The CSV import endpoint accepts more date formats, described in the next section.']),P('Camera display behavior','H2x'),P('The monitor runs in a background thread. It reads frames, calls the processing function, saves a latest preview image, stores the last status and exposes a status endpoint. Aim the camera at a vehicle. A camera successfully reading an indoor room can still show no plate because there is no car plate in view.','BodyX'),P('Performance terms','H2x'),P('The 32.6 FPS number describes a warmed-up detector on a still image. It does not include the full camera, OCR, database and browser path. Video processing currently samples approximately 6 frames per second. To claim 24 FPS, measure the complete path using the same hardware and report the average and test conditions.','CalloutX'),PageBreak()]
story += [P('4. Booking data: CSV import and manual entry','H1x'),P('The dashboard has a Register Booking area for entering a single booking. It also has a CSV import option and a downloadable template. The import endpoint accepts CSV files. It does not directly accept an Excel .xlsx file. To use Excel, open the workbook and save a copy as CSV UTF-8, then upload that CSV.','BodyX'),P('CSV columns','H2x'),P('Use the downloaded template when possible. The sample file uses these headings:','BodyX'),P('customer_name, phone, vehicle_number, vehicle_model, booking_date, booking_time, service_type, status, advisor_id, advisor_name','CodeX'),P('Example row (safe demo values)','H2x'),P('Gate Demo Presentation, 9876543216, KL02HB1234, Mercedes-Benz Demo Vehicle, 2026-11-23, 15:30, General Service, confirmed, 1, Service Advisor 1','CodeX'),P('The registration can be stored without spaces. The application normalizes it for matching and formats recognized output with spaces, for example KL 07 AB 1234. Required advisor IDs must refer to an active advisor when importing. The application may also accept an exact advisor name where the endpoint supports it. Use the template columns to avoid header errors.','BodyX'),P('Supported date formats for CSV import','H2x'),P('YYYY-MM-DD, DD-MM-YYYY, DD/MM/YYYY, or YYYY/MM/DD. Example: 23-11-2026 is interpreted as 23 November 2026 by the importer. The booking lookup fallback reads the sample CSV using ISO format YYYY-MM-DD, so keep sample_bookings.csv dates in ISO format.','BodyX'),P('Import safety and common messages','H2x'),bullet(['The import validates rows before saving. A bad row prevents a partial import.','Duplicate bookings may be skipped instead of inserted again.','If the import says the advisor is invalid, check the advisor ID or name and make sure the advisor account is active.','If the import says an ISO date is invalid for a date such as 23-11-2026, use the import form, which accepts DD-MM-YYYY, or save as 2026-11-23.']),P('Direct Excel upload is a future enhancement. CSV is the current supported upload format.','CalloutX'),PageBreak()]
story += [P('5. Source files and functions','H1x'),P('This section maps the project source to its responsibility. The application code may change; line numbers are deliberately omitted. Use the file names in the workspace to follow the logic.','BodyX')]
files=[
('app/main.py','FastAPI application and endpoints. home and dashboard_page serve the HTML pages. health reports service status. login and logout manage sessions. current_user returns the logged-in identity. create_advisor and list_advisors manage advisor accounts. list_bookings, booking_details and create_booking read or create booking records. parse_booking_import_date accepts supported import dates. download_booking_template serves the CSV template. import_bookings_csv validates and imports rows. advisor_dashboard, advisor_notifications and mark_notification_read serve advisor-specific pages and notification state. update_notification changes read or completed state. admin_dashboard and admin_notifications serve admin data. process_frame runs plate detection, OCR, matching and persistence for one image. process_camera_frame adapts it for the monitor. upload_video samples a video, keeps the best result per plate and returns recognized results. get_camera_source selects the configured camera source. start_monitor, stop_monitor and monitor_status control live capture.'),
('app/config.py','Settings class loads environment settings such as database connection, model path, detector confidence, image size, region of interest, Tesseract path and duplicate detection window. Values belong in a private local environment file. Do not publish credentials.'),
('app/database.py','Creates the SQLAlchemy database engine and session factory. get_db opens a database session for a request and closes it after the request, including when an error occurs.'),
('app/models.py','Defines Advisor, Booking, Detection and Notification tables. Relationships connect an advisor to bookings and notifications, a booking to detections, and a detection to notifications.'),
('app/schemas.py','Pydantic request and response models. AdvisorCreate and booking request models validate API input. BookingOut serializes a booking from a SQLAlchemy object.'),
('app/security/auth.py','hash_password uses a random salt and PBKDF2-HMAC-SHA256. verify_password recalculates the hash and compares safely. get_current_user checks the session and advisor activity. require_admin and require_advisor block requests from the wrong role.'),
('app/services/detector.py','PlateDetector.__init__ resolves the configured model path. load_model loads YOLO once and errors if the file is missing. apply_roi crops the configured region. detect runs inference, checks orientations, maps coordinates back to the original frame and returns box, confidence and crop.'),
('app/services/ocr.py','_configure_tesseract sets a configured executable or checks common Windows locations. preprocess_plate makes enlarged, denoised, contrast-adjusted and thresholded image variants. read_plate runs Tesseract on the variants and keeps the strongest plausible cleaned result.'),
('app/services/plate_utils.py','normalize_plate keeps uppercase letters and digits. clean_indian_plate applies position-aware character fixes and validates the registration pattern. format_indian_plate adds readable spaces. is_plausible_indian_plate tests whether cleanup produces a valid pattern.'),
('app/services/booking_service.py','get_indian_today uses the India time zone. _one_edit_apart checks one inserted, missing or substituted character. _csv_bookings reads today\'s fallback sample bookings. find_booking searches database exact match first, then a unique fuzzy match, then the CSV.'),
('app/services/monitor.py','CameraMonitor.start creates a worker thread. _run opens the camera, reads frames, calls the supplied processing function, writes a preview and updates monitor status. stop signals the worker and releases the capture. status returns current monitor state. A lock protects shared thread data.'),
('static/login.html','Login page structure and form. JavaScript sends login information to the API; the server decides whether it is valid.'),
('static/index.html','Dashboard page structure: navigation, booking forms and table, video upload controls, live monitor and notification containers.'),
('static/app.js','api sends requests and handles errors. showMessage and hideMessage update form messages. escapeHtml makes displayed user text safer. formatDate, formatTime and statusClass format values. showPage and initializeApp control page visibility and initial loading. loadDashboard, loadBookings, loadAdvisors and loadNotifications request data. renderBookings, renderVideoResults, renderLiveRecognition and renderNotifications update the screen. safeLocalUploadUrl and formatConfidence format detection output. loadMonitorStatus checks camera state. updateNotification saves read/completed state. startBackgroundRefresh periodically refreshes data. DOMContentLoaded starts initialization.'),
('static/style.css','Controls colors, typography, spacing, responsive layout, tables, forms and status styling. It does not perform plate recognition.'),
('requirements.txt','Lists the Python packages required by the application, including FastAPI, SQLAlchemy, OpenCV, Ultralytics, PyTorch dependency, pytesseract, numpy and dotenv support. Install in the project virtual environment.'),
('sample_bookings.csv','Demo booking data. The vehicle plate, date, time and advisor columns are used for lookup. Keep fallback dates in YYYY-MM-DD format.'),
('create_advisor_logins.py','Interactive helper that asks for a new temporary password for each advisor, hashes it, activates the advisor and saves changes.'),
('create_demo_account.py','Creates or updates a demo advisor. The source currently contains a demonstration password. Change it before using the system outside a private classroom demo, and do not place account passwords in a public presentation.'),
('task.py and task.ipynb','task.py currently only prints a short test message. The notebook is not part of the running web application. The main application starts through the documented Uvicorn command.'),
('models/best.pt','Trained YOLO model weights used by the detector. This is a binary model file, not readable Python source. The original training dataset and training script are not present in the project folder.'),
('uploads/','Stores uploaded video or generated preview/detection images. Avoid committing real customer images or private data to a public repository.'),
('.env','Private local configuration for secrets and machine-specific paths. Do not print, email, upload or include its contents in presentation material.')]
for name,desc in files:
 story += [P(name,'H2x'),P(desc,'BodyX')]
story += [PageBreak(),P('6. Common errors and fixes','H1x'),table([['Error or symptom','Likely cause','What to check or do'],['Invalid isoformat string: 20-11-2026','Importer tried to parse a day-month date using ISO parsing.','Use the current CSV import, which accepts DD-MM-YYYY. Or save the date as 2026-11-20. Keep fallback sample CSV dates in ISO format.'],['Cannot read properties of null (reading reset)','JavaScript tried to reset a form element that was not on the current page.','Guard the form reference before calling reset, for example if (form) form.reset(). Reload the page to get the current app.js.'],['Live camera open, but no plate','Wrong camera source, no car in view, plate too small, blur, glare, angle or low light.','Confirm the camera sees a vehicle. Move closer, focus, improve light, use the correct camera index and check the monitor status/error.'],['Every frame says no plate','The model does not find a valid plate in those frames, or the application is showing raw frame status.','Use a test video with a visible plate, check model file and ROI, and review only recognized result cards. Confirm output after a new video upload.'],['Plate text is wrong or incomplete','Low crop resolution, glare, dirt, plate at an angle or OCR confusion.','Use a sharper/larger crop, better light and a near-frontal view. Review the saved frame and crop. Add gate examples to future tuning.'],['Plate detected but booking not matched','No booking for today, registration mismatch, date mismatch, or inactive/wrong advisor in imported data.','Check normalized plate and booking date in India time. Confirm row exists in the database or sample CSV. Compare exact plate first.'],['YOLO model not found','Model path points to the wrong file.','Confirm models/best.pt exists and set the configured model path correctly. Do not rename the model without updating config.'],['Tesseract executable not found','Tesseract OCR is not installed or the executable path is not set.','Install Tesseract on the PC and set TESSERACT_CMD to its local executable path. Restart the app.'],['Database URL or connection error','Missing private connection setting or database is offline/unreachable.','Check that the database service is running and the private DATABASE_URL setting is valid. Never paste the connection string into the report.'],['CSV import rejected','Wrong headers, invalid advisor, bad date, wrong file type or malformed row.','Download the template, save as CSV UTF-8, use supported dates, check required advisor, then retry. Import currently accepts .csv only.'],['Video rejected or cannot open','Unsupported codec/extension, corrupt upload or size above 200 MB.','Use MP4, AVI, MOV or MKV in a supported codec. Keep the file below 200 MB and test it in a video player first.'],['401 or 403 API error','Session expired, user signed out, account inactive or role lacks permission.','Sign in again. Use admin functions with admin account. Confirm advisor account is active.'],['Completed/read status did not change','Request failed, browser has stale code or notification belongs to another user.','Refresh the page, check browser network response, verify the current user and retry the status action.']],[48*mm,55*mm,70*mm]),Spacer(1,6),P('The first live camera check showed an indoor room rather than a vehicle. That confirms the camera stream can be open while plate detection correctly finds nothing. Point the camera at a visible registration plate for a meaningful test.','CalloutX'),PageBreak()]
story += [P('7. Demo and test plan','H1x'),P('Prepare before the presentation','H2x'),bullet(['Start the database and application. Check that the health endpoint responds.','Sign in using the configured admin account. Keep credentials private.','Import the provided CSV using Register Booking if its rows are not already in the database. The sample CSV includes a presentation booking dated 23 November 2026.','Make sure the camera has permission and points at a vehicle if you will show live recognition.','Keep the sample video ready as a backup.']),P('Video demo steps','H2x'),table([['Action','Expected result'],['Upload prepared gate video','The video processes and returns one best frame for each recognized plate.'],['Show matched sample plate','KL 02 HB 1234 can match Gate Demo Presentation at 3:30 PM with Service Advisor 1 when the sample row is present and the app date/data align.'],['Show unmatched example','The result displays the recognized plate and says no booking matched.'],['Show no-plate scene','No recognition card appears when no valid plate is recognized.'],['Update notification','Use the notification controls to mark it read/unread or completed/reopen.']],[55*mm,118*mm]),P('Ten unseen plate evaluation','H2x'),P('Prepare ten separate examples and write down the correct registration before the test. Include clear plates, one dirty or angled plate, and one night or low-light plate. Count a plate as correct only when the whole registration is read correctly. Record correct reads divided by ten. The target is at least 8/10. The project has not yet completed this evaluation, so do not claim the target has been met until the test sheet shows it.','BodyX'),P('FPS test','H2x'),P('Use the same camera/video, computer, resolution and lighting for each run. Measure the time for the full frame-to-screen path, not only YOLO inference. Calculate processed frames divided by elapsed seconds. The target is 24 FPS. The present video sampling rate is around 6 FPS, so the full system needs optimization and a new benchmark.','BodyX'),PageBreak()]
story += [P('8. Current limits and next steps','H1x'),table([['Requirement','Current status','Next action'],['Video/live camera plate detection','Implemented in the application. Live results depend on pointing the camera at a readable plate.','Test at the actual gate and verify the camera source.'],['Indian format OCR','Cleanup and formatting functions exist.','Measure accuracy on a separate set of ten or more unseen plates.'],['Booking match','Database plus CSV fallback. CSV upload supports booking import.','Confirm demo date, booking rows and active advisor before presentation.'],['Screen with image, plate and booking','Browser dashboard presents recognition results. Video keeps best frame per plate.','Verify current deployed app build during the live demo.'],['24 FPS benchmark','Not verified end-to-end. Detector-only still benchmark is 32.6 FPS; video sampling is about 6 FPS.','Profile and optimize the full path. Record conditions and measured average.'],['8/10 unseen examples','Not verified.','Run a labeled test with ten unseen images or clips and preserve the results sheet.'],['Excel upload','Direct .xlsx import not available. CSV import is available.','Add .xlsx support only if needed; until then export Excel to CSV UTF-8.'],['Dirty/angled and night examples','No completed scored test result yet.','Include these conditions in the ten-plate test.']],[46*mm,58*mm,69*mm]),Spacer(1,8),P('Recommended order of work','H2x'),bullet(['First, confirm correct camera framing and booking data.','Second, run and record the ten unseen plate test, including difficult conditions.','Third, profile the video and live capture path to identify the slowest step.','Fourth, improve accuracy and speed based on measured failures.','Finally, repeat both tests and update the presentation with verified results.']),P('Presentation message','H2x'),P('Describe the current application as a working prototype for camera/video recognition and booking lookup. Explain the 32.6 FPS figure as detector-only, not full system speed. Say that the 24 FPS and 8/10 targets still need formal verification. Demonstrate a matching booking, an unmatched plate, and a camera view with no vehicle if asked.','CalloutX'),P('Project file map complete as of this guide. Keep private environment values and real customer records out of shared presentation materials.','SmallX')]

